mapper.update:
update aden_outbox
   set outbox_state = 'CLAIMED', attempts = attempts + 1,
       claim_token = #{claimToken}, claimed_until = #{claimedUntil}, updated_at = #{now}
 where workspace_id = #{workspaceId}
   and outbox_id = #{outboxId}
   and ((outbox_state = 'PENDING' and available_at <= #{now})
     or (outbox_state = 'CLAIMED' and claimed_until <= #{now}))

update aden_outbox
   set outbox_state = 'PUBLISHED', claim_token = null, claimed_until = null,
       last_error = null, published_at = #{publishedAt}, updated_at = #{publishedAt}
 where workspace_id = #{workspaceId} and outbox_id = #{outboxId}
   and outbox_state = 'CLAIMED' and claim_token = #{claimToken}

update aden_outbox
   set outbox_state = 'PENDING', claim_token = null, claimed_until = null,
       last_error = #{error}, available_at = #{nextAvailableAt}, updated_at = #{updatedAt}
 where workspace_id = #{workspaceId} and outbox_id = #{outboxId}
   and outbox_state = 'CLAIMED' and claim_token = #{claimToken}

update aden_outbox
   set outbox_state = 'DEAD', claim_token = null, claimed_until = null,
       last_error = #{error}, updated_at = #{updatedAt}
 where workspace_id = #{workspaceId} and outbox_id = #{outboxId}
   and outbox_state = 'CLAIMED' and claim_token = #{claimToken}
